"use client"

// Export of the findings for vessel review: PDF (layout of this screen, with a fillable status dropdown per finding)
// or Excel (status dropdown column). The file is generated by the server from the selected run.

import { useEffect, useState } from "react"
import { FINDINGS_BANNER } from "@/lib/export/brand"
import { type ExportScope, exportParams, type FindingFilter, SCOPE_LABEL } from "@/lib/export/findings-filter"
import { formatTime } from "../api"
import { Button, cn } from "../ui"
import type { Ctx } from "./types"

export function ExportFindings({ ctx, filter, shown, onClose }: { ctx: Ctx; filter: FindingFilter; shown: number; onClose: () => void }) {
  const run = ctx.run!
  const all = ctx.result?.findings ?? []
  const [format, setFormat] = useState<"pdf" | "xlsx">("pdf")
  const [scope, setScope] = useState<ExportScope>("errors-warnings")
  const [notes, setNotes] = useState(false)

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onClose()
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [onClose])

  const counts: Record<ExportScope, number> = { "errors-warnings": all.filter((f) => f.severity !== "info").length, all: all.length, filter: shown }
  const params = exportParams(scope, filter)
  params.set("format", format)
  if (notes) params.set("notes", "1")
  const href = `/api/sessions/${ctx.data.session._id}/runs/${run._id}/findings-export?${params}`

  const option = (active: boolean) => cn("flex cursor-pointer items-start gap-2 rounded-lg border px-3 py-2 text-sm", active ? "border-primary bg-info-bg" : "hover:bg-muted")

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" role="dialog" aria-modal="true" aria-labelledby="export-title" onClick={onClose}>
      <div className="w-full max-w-lg rounded-xl border bg-card shadow-xl" onClick={(e) => e.stopPropagation()}>
        <header className="flex items-center justify-between border-b px-4 py-3">
          <h2 id="export-title" className="text-sm font-bold">Export findings</h2>
          <span className="text-xs text-muted-foreground">Run {formatTime(run.startedAt)}</span>
        </header>
        <div className="flex flex-col gap-4 p-4">
          <fieldset className="flex flex-col gap-2">
            <legend className="mb-1 text-xs font-bold text-muted-foreground">FORMAT</legend>
            <label className={option(format === "pdf")}>
              <input type="radio" name="format" className="mt-1" checked={format === "pdf"} onChange={() => setFormat("pdf")} />
              <span><strong>PDF for the vessel</strong><br /><span className="text-xs text-muted-foreground">Laid out like this screen: one card per finding with its source lines, calculation and recommended check, and a fillable Investigation status dropdown and Vessel remarks box.</span></span>
            </label>
            <label className={option(format === "xlsx")}>
              <input type="radio" name="format" className="mt-1" checked={format === "xlsx"} onChange={() => setFormat("xlsx")} />
              <span><strong>Excel</strong><br /><span className="text-xs text-muted-foreground">One row per finding with an Investigation status dropdown and a Vessel remarks column; calculations on a second sheet.</span></span>
            </label>
          </fieldset>
          <fieldset className="flex flex-col gap-2">
            <legend className="mb-1 text-xs font-bold text-muted-foreground">FINDINGS</legend>
            {(Object.keys(SCOPE_LABEL) as ExportScope[]).map((s) => (
              <label key={s} className={option(scope === s)}>
                <input type="radio" name="scope" className="mt-1" checked={scope === s} onChange={() => setScope(s)} disabled={counts[s] === 0} />
                <span>{SCOPE_LABEL[s]} <span className="text-muted-foreground">({counts[s]})</span></span>
              </label>
            ))}
          </fieldset>
          <label className="flex items-start gap-2 text-sm">
            <input type="checkbox" className="mt-1" checked={notes} onChange={(e) => setNotes(e.target.checked)} />
            <span>Include office investigation notes <span className="text-xs text-muted-foreground">(off by default — the file is meant for the vessel)</span></span>
          </label>
          <p className="text-xs text-muted-foreground">Every page and sheet is marked {FINDINGS_BANNER}. The export is recorded in the audit history.</p>
          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={onClose}>Cancel</Button>
            <a className="inline-flex h-9 items-center rounded-lg bg-primary px-3 text-sm font-semibold text-primary-foreground hover:opacity-90" href={href} onClick={() => setTimeout(onClose, 300)}>
              Download {format === "pdf" ? "PDF" : "Excel"} ({counts[scope]})
            </a>
          </div>
        </div>
      </div>
    </div>
  )
}
